tool_calls.arguments:
{"command": "kubectl -n default patch deployment app --type=strategic -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "livenessProbe": {
              "initialDelaySeconds": null,
              "periodSeconds": 10,
              "failureThreshold": 3,
              "successThreshold": 1,
              "timeoutSeconds": 1,
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"}
            },
            "startupProbe": {
              "failureThreshold": 15,
              "periodSeconds": 2,
              "successThreshold": 1,
              "timeoutSeconds": 1,
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"}
            }
          }
        ]
      }
    }
  }
}' 2>&1"}

